-- Seasonal stock level management for a toy distributor.

DROP TABLE IF EXISTS toys;
DROP TABLE IF EXISTS brands;

CREATE TABLE brands (
    brand_id   INTEGER      PRIMARY KEY,
    brand_name VARCHAR(60)  NOT NULL,
    country    VARCHAR(40)  NOT NULL
);

INSERT INTO brands (brand_id, brand_name, country) VALUES (1, 'Steiff', 'germany');
INSERT INTO brands (brand_id, brand_name, country) VALUES (2, 'Schleich', 'germany');
INSERT INTO brands (brand_id, brand_name, country) VALUES (3, 'Tomy', 'japan');
INSERT INTO brands (brand_id, brand_name, country) VALUES (4, 'Bandai', 'japan');
INSERT INTO brands (brand_id, brand_name, country) VALUES (5, 'Lego', 'denmark');

-- Step 1: every brand originating from germany.
SELECT brand_id,
       brand_name,
       country
FROM brands
WHERE country = 'germany';

CREATE TABLE toys (
    toy_id      INTEGER      PRIMARY KEY,
    brand_id    INTEGER      NOT NULL,
    toy_name    VARCHAR(60)  NOT NULL,
    age_group   VARCHAR(20)  NOT NULL,
    stock_level INTEGER      NOT NULL,
    CONSTRAINT fk_toys_brand FOREIGN KEY (brand_id) REFERENCES brands (brand_id)
);

INSERT INTO toys (toy_id, brand_id, toy_name, age_group, stock_level) VALUES (1, 3, 'Stacking Rings', 'toddlers', 20);
INSERT INTO toys (toy_id, brand_id, toy_name, age_group, stock_level) VALUES (2, 3, 'Soft Blocks Set', 'toddlers', 45);
INSERT INTO toys (toy_id, brand_id, toy_name, age_group, stock_level) VALUES (3, 4, 'Plush Robot Pal', 'toddlers', 30);
INSERT INTO toys (toy_id, brand_id, toy_name, age_group, stock_level) VALUES (4, 1, 'Classic Teddy', 'toddlers', 12);
INSERT INTO toys (toy_id, brand_id, toy_name, age_group, stock_level) VALUES (5, 5, 'Farm Bricks', 'preschool', 80);

-- Step 2: japanese brands whose toddler toys have dropped below fifty units,
-- summarised per brand and ranked by how critical the shortage is.
SELECT b.brand_name,
       AVG(t.stock_level)
           AS average_stock_level
FROM brands
    AS b
INNER JOIN toys
    AS t
    ON b.brand_id = t.brand_id
WHERE b.country = 'japan'
  AND t.age_group = 'toddlers'
  AND t.stock_level < 50
GROUP BY b.brand_name
ORDER BY average_stock_level ASC;

