DROP VIEW IF EXISTS evening_documentaries;
DROP TABLE IF EXISTS screenings;
DROP TABLE IF EXISTS cinemas;

CREATE TABLE cinemas (
    cinema_id    INTEGER PRIMARY KEY,
    cinema_name  VARCHAR(80) NOT NULL,
    screen_count INTEGER NOT NULL
);

CREATE TABLE screenings (
    screening_id INTEGER PRIMARY KEY,
    cinema_id    INTEGER NOT NULL REFERENCES cinemas (cinema_id),
    film_title   VARCHAR(120) NOT NULL,
    tickets_sold INTEGER NOT NULL,
    showtime     TIME NOT NULL
);

CREATE VIEW evening_documentaries AS
SELECT screening_id,
       cinema_id,
       film_title,
       tickets_sold,
       showtime
FROM screenings
WHERE film_title LIKE '%Documentary%'
  AND showtime >= '18:00:00';

