    ORDER BY dark_high_speed_logs DESC;

    SELECT instruments.serial_number,
           instruments.wood_type,
           maintenance_logs.wheel_speed
    FROM instruments
    JOIN maintenance_logs
        ON maintenance_logs.instrument_id = instruments.instrument_id
    WHERE maintenance_logs.session_id = session
        AND maintenance_logs.rosin_type = 'light'
        AND maintenance_logs.friction_resistance = 0
    ORDER BY instruments.serial_number;

    SELECT maple_instruments.serial_number,
           COUNT(*) AS dark_high_speed_logs,
           MAX(maintenance_logs.wheel_speed) AS top_wheel_speed
    FROM maple_instruments
    JOIN maintenance_logs
